#include "edudb.hpp"
#include <algorithm>
#include <chrono>
#include <filesystem>
#include <fstream>
#include <future>
#include <iostream>
#include <thread>
using namespace edudb;using namespace std::chrono_literals;namespace fs=std::filesystem;
namespace {
std::size_t checks=0;json observations=json::array();
void need(bool b,const std::string& why){++checks;if(!b)throw std::runtime_error(why);}
json ok(Engine& e,const std::string& s,const std::string& sql){auto r=e.execute(s,sql);need(r.value("ok",false),sql+": "+r.dump());return r;}
void error(Engine& e,const std::string& s,const std::string& sql,const std::string& code){auto r=e.execute(s,sql);need(!r.value("ok",true)&&r["error"]["code"]==code,sql+" expected "+code+": "+r.dump());}
template<class F>void until(F f,const std::string& why){auto end=std::chrono::steady_clock::now()+2s;while(std::chrono::steady_clock::now()<end){if(f())return;std::this_thread::sleep_for(1ms);}throw std::runtime_error(why);}
void queued(Engine& e,const std::string& kind){until([&]{auto s=e.diagnostics();for(const auto& q:s["queues"])if(kind=="table"?q["resource"].get<std::string>().rfind("table:",0)==0:q.value("kind",std::string())=="INTEGER_RANGE"){observations.push_back({{"kind","real_sql_wait"},{"snapshot",s}});return true;}return false;},"Actual "+kind+" lock queue missing");}
json done(std::future<json>& f,const std::string& why){need(f.wait_for(4s)==std::future_status::ready,why+" bounded completion");auto r=f.get();need(r.value("ok",false),why+": "+r.dump());return r;}
void rows(Engine& e,const std::string& s,const std::string& sql,const json& expected){need(ok(e,s,sql)["rows"]==expected,"Rows mismatch: "+sql);}
void record(Engine& e,const std::string& s){ok(e,s,"SET LOCK GRANULARITY RECORD");}
void run(const fs::path& path){Engine e(path.u8string(),3);auto seed=e.open_session(),a=e.open_session(),b=e.open_session(),c=e.open_session();ok(e,seed,"CREATE TABLE t(id INTEGER PRIMARY KEY,v INTEGER)");ok(e,seed,"INSERT INTO t VALUES(1,1),(2,2),(10,10),(30,30)");record(e,a);record(e,b);record(e,c);
    ok(e,a,"BEGIN");auto read=ok(e,a,"SELECT v FROM t WHERE id=1");need(read["locking"]["effective"]=="RECORD"&&read["locking"]["table_mode"]=="IS","Actual record read plan");ok(e,b,"BEGIN");auto write=std::async(std::launch::async,[&]{return e.execute(b,"UPDATE t SET v=22 WHERE id=2");});need(write.wait_for(1200ms)==std::future_status::ready,"Disjoint logical writer not serialized by hidden tableS");done(write,"Disjoint writer");ok(e,b,"COMMIT");rows(e,a,"SELECT v FROM t WHERE id=1",json::array({json::array({1})}));rows(e,a,"SELECT v FROM t WHERE id=2",json::array({json::array({22})}));observations.push_back({{"kind","disjoint_read_write"},{"read_locking",read["locking"]},{"snapshot",e.diagnostics()}});ok(e,a,"COMMIT");
    ok(e,a,"BEGIN");ok(e,b,"BEGIN");ok(e,a,"UPDATE t SET v=111 WHERE id=1");ok(e,b,"UPDATE t SET v=222 WHERE id=2");ok(e,a,"COMMIT");auto wal=e.diagnostics()["storage"]["wal_bytes"];error(e,b,"COMMIT","SERIALIZATION_FAILURE");need(e.diagnostics()["storage"]["wal_bytes"]==wal,"Record same-page loser rejected before WAL");need(!e.diagnostics()["storage"]["recovery_required"].get<bool>(),"Conflict does not poison engine");ok(e,b,"ROLLBACK");rows(e,seed,"SELECT v FROM t WHERE id=2",json::array({json::array({22})}));
    ok(e,a,"BEGIN");ok(e,a,"UPDATE t SET v=999 WHERE id=1");ok(e,b,"UPDATE t SET v=25 WHERE id=2");auto refresh_wal=e.diagnostics()["storage"]["wal_bytes"];error(e,a,"SELECT v FROM t WHERE id=1","SERIALIZATION_FAILURE");need(e.diagnostics()["storage"]["wal_bytes"]==refresh_wal,"Dirty base cannot be spliced into a newer statement view");ok(e,a,"ROLLBACK");rows(e,seed,"SELECT v FROM t WHERE id=1",json::array({json::array({111})}));ok(e,seed,"UPDATE t SET v=22 WHERE id=2");
    ok(e,a,"BEGIN");ok(e,a,"SELECT v FROM t WHERE id=1");ok(e,a,"SAVEPOINT prior_view");ok(e,b,"UPDATE t SET v=26 WHERE id=2");rows(e,a,"SELECT v FROM t WHERE id=2",json::array({json::array({26})}));ok(e,a,"ROLLBACK TO prior_view");rows(e,a,"SELECT v FROM t WHERE id=2",json::array({json::array({26})}));ok(e,a,"COMMIT");ok(e,seed,"UPDATE t SET v=22 WHERE id=2");
    ok(e,a,"BEGIN");auto gap=ok(e,a,"SELECT id FROM t WHERE id>10 AND id<20");need(gap["rows"].empty()&&gap["locking"]["effective"]=="RECORD","Empty result still locks real open gap");ok(e,b,"BEGIN");auto fifteen=std::async(std::launch::async,[&]{return e.execute(b,"INSERT INTO t VALUES(15,15)");});queued(e,"range");auto twenty=ok(e,c,"INSERT INTO t VALUES(20,20)");need(twenty["locking"]["effective"]=="RECORD","Open upper endpoint20 is not blocked");std::string growth="INSERT INTO t VALUES ";for(int id=100;id<300;++id){if(id!=100)growth+=",";growth+="("+std::to_string(id)+","+std::to_string(id)+")";}ok(e,c,growth);need(fifteen.wait_for(0ms)!=std::future_status::ready,"INSERT15 remains blocked while20 and index splits commit");ok(e,a,"COMMIT");done(fifteen,"Gap waiter after actual root splits");ok(e,b,"COMMIT");rows(e,seed,"SELECT COUNT(*) FROM t",json::array({json::array({206})}));ok(e,seed,"DELETE FROM t WHERE id>=100");
    ok(e,a,"BEGIN");ok(e,b,"BEGIN");ok(e,a,"SELECT v FROM t WHERE id=1");ok(e,b,"SELECT v FROM t WHERE id=2");auto cycle=std::async(std::launch::async,[&]{return e.execute(a,"UPDATE t SET v=23 WHERE id=2");});queued(e,"range");error(e,b,"UPDATE t SET v=12 WHERE id=1","DEADLOCK");done(cycle,"Real SQL range deadlock survivor");auto d=e.diagnostics();bool event=false;for(const auto& item:d["events"])if(item["kind"]=="deadlock_cycle"){auto ids=item["details"]["cycle"].get<std::vector<std::uint64_t>>();need(item["details"]["victim"]==*std::max_element(ids.begin(),ids.end()),"Actual greatest transaction victim");event=true;}need(event,"Actual SQL range cycle event");observations.push_back({{"kind","sql_range_deadlock"},{"snapshot",d}});ok(e,a,"COMMIT");ok(e,b,"ROLLBACK");
    ok(e,a,"BEGIN");auto fallback=ok(e,a,"SELECT id FROM t WHERE v>0");need(fallback["locking"]["effective"]=="TABLE","Non-key predicate uses real coarse fallback");ok(e,b,"BEGIN");auto blocked=std::async(std::launch::async,[&]{return e.execute(b,"UPDATE t SET v=31 WHERE id=30");});queued(e,"table");need(blocked.wait_for(0ms)!=std::future_status::ready,"Actual fallback tableS blocks disjoint RECORD IX");ok(e,a,"COMMIT");done(blocked,"Fallback writer");ok(e,b,"COMMIT");
    for(const auto& query:{"SELECT * FROM t WHERE id=1 OR id=2","SELECT * FROM t","SELECT * FROM t INNER JOIN t u ON t.id=u.id WHERE t.id=1"}){auto r=ok(e,a,query);need(r["locking"]["effective"]=="TABLE","Unsupported SELECT is table fallback");}
    auto computed=ok(e,a,"INSERT INTO t VALUES(40+1,41)");need(computed["locking"]["effective"]=="TABLE","Unproved INSERT key expression is fallback");auto pkchange=ok(e,a,"UPDATE t SET id=id+1 WHERE id=41");need(pkchange["locking"]["effective"]=="TABLE","Unproved key migration is fallback");auto target=ok(e,a,"UPDATE t SET id=43 WHERE id=42");need(target["locking"]["effective"]=="RECORD"&&target["locking"]["intervals"].size()==2,"Proved key migration locks old range and new point");rows(e,a,"SELECT id FROM t WHERE id=43",json::array({json::array({43})}));
    ok(e,seed,"BEGIN");ok(e,seed,"SELECT v FROM t WHERE id=1");ok(e,b,"BEGIN");auto default_wait=std::async(std::launch::async,[&]{return e.execute(b,"UPDATE t SET v=24 WHERE id=2");});queued(e,"table");need(default_wait.wait_for(0ms)!=std::future_status::ready,"Default TABLE SELECT still holds actual tableS");ok(e,seed,"COMMIT");done(default_wait,"Default TABLE guard release");ok(e,b,"COMMIT");
    ok(e,a,"BEGIN");ok(e,a,"SELECT v FROM t WHERE id=1");ok(e,b,"BEGIN");auto fifo_writer=std::async(std::launch::async,[&]{return e.execute(b,"UPDATE t SET v=112 WHERE id=1");});queued(e,"range");ok(e,c,"BEGIN");auto fifo_reader=std::async(std::launch::async,[&]{return e.execute(c,"SELECT v FROM t WHERE id=1");});until([&]{auto state=e.diagnostics();return state["queues"].size()>=2;},"SQL FIFO reader queue missing");observations.push_back({{"kind","sql_fifo_predecessor"},{"snapshot",e.diagnostics()}});ok(e,a,"COMMIT");done(fifo_writer,"FIFO SQL writer");need(fifo_reader.wait_for(0ms)!=std::future_status::ready,"Late SQL reader cannot barge before queued writer commits");ok(e,b,"COMMIT");need(done(fifo_reader,"FIFO SQL reader")["rows"]==json::array({json::array({112})}),"FIFO reader sees committed predecessor value");ok(e,c,"COMMIT");
    ok(e,a,"BEGIN");ok(e,a,"SELECT id FROM t WHERE id=80");ok(e,b,"BEGIN");auto move=std::async(std::launch::async,[&]{return e.execute(b,"UPDATE t SET id=80 WHERE id=43");});queued(e,"range");need(move.wait_for(0ms)!=std::future_status::ready,"New primary key point is protected before migration");ok(e,a,"COMMIT");done(move,"Proved key point migration");ok(e,b,"COMMIT");rows(e,c,"SELECT id FROM t WHERE id=80",json::array({json::array({80})}));
    ok(e,a,"BEGIN");ok(e,a,"SELECT id FROM t WHERE id=1");auto import=std::async(std::launch::async,[&]{return e.import_data(b,{{"format","csv"},{"table","t"},{"header",true},{"content","id,v\r\n50,50\r\n"}});});queued(e,"table");need(import.wait_for(0ms)!=std::future_status::ready,"CSV import remains true tableX fallback");ok(e,a,"COMMIT");done(import,"CSV coarse fallback");
    ok(e,a,"BEGIN");ok(e,a,"UPDATE t SET v=999 WHERE id=1");auto export_csv=std::async(std::launch::async,[&]{return e.export_data(b,{{"format","csv"},{"table","t"}});});queued(e,"table");ok(e,a,"ROLLBACK");auto csv=done(export_csv,"CSV tableS fallback");need(csv["content"].get<std::string>().find("999")==std::string::npos,"CSV fallback excludes uncommitted value");
    auto closing=e.open_session();record(e,closing);ok(e,closing,"BEGIN");ok(e,closing,"SELECT id FROM t WHERE id=1");ok(e,b,"BEGIN");auto closed_wait=std::async(std::launch::async,[&]{return e.execute(b,"UPDATE t SET v=113 WHERE id=1");});queued(e,"range");e.close_session(closing);done(closed_wait,"Close-session rollback releases interval/intention locks");ok(e,b,"COMMIT");
    auto contradictory=ok(e,a,"SELECT * FROM t WHERE id>5 AND id<5");need(contradictory["rows"].empty()&&contradictory["locking"]["intervals"][0]["empty"]==true,"Contradictory integer interval safely empty");ok(e,a,"INSERT INTO t VALUES(-9223372036854775808,0),(9223372036854775807,0)");rows(e,a,"SELECT COUNT(*) FROM t WHERE id>9223372036854775807",json::array({json::array({0})}));
    ok(e,seed,"CREATE TABLE n(k INTEGER,v INTEGER)");ok(e,seed,"CREATE TABLE s(k VARCHAR(10) PRIMARY KEY)");ok(e,seed,"CREATE TABLE compound(k INTEGER,v INTEGER,PRIMARY KEY(k,v))");for(const auto& query:{"SELECT * FROM n WHERE k=1","SELECT * FROM s WHERE k='a'","SELECT * FROM compound WHERE k=1 AND v=1"})need(ok(e,a,query)["locking"]["effective"]=="TABLE","Non-simple-integer key fallback");
    ok(e,a,"BEGIN");error(e,a,"SET LOCK GRANULARITY TABLE","TRANSACTION_ACTIVE");ok(e,a,"ROLLBACK");for(const auto& protocol:{"SNAPSHOT","OCC","TIMESTAMP","THOMAS"})error(e,a,std::string("BEGIN PROTOCOL ")+protocol,"INVALID_LOCK_GRANULARITY");ok(e,a,"SET LOCK GRANULARITY TABLE");ok(e,a,"BEGIN PROTOCOL SNAPSHOT");ok(e,a,"COMMIT");record(e,a);ok(e,a,"BEGIN READ ONLY");error(e,a,"UPDATE t SET v=0 WHERE id=1","READ_ONLY_TRANSACTION");ok(e,a,"ROLLBACK");
    ok(e,seed,"VERIFY");e.close_session(a);e.close_session(b);e.close_session(c);e.close_session(seed);
}
void aries(const fs::path& path){StorageOptions o;o.recovery_mode="ARIES_PAGE";Engine e(path.u8string(),3,32u*1024u*1024u,o);auto s=e.open_session();error(e,s,"SET LOCK GRANULARITY RECORD","ARIES_RECORD_UNSUPPORTED");ok(e,s,"CREATE TABLE t(id INTEGER PRIMARY KEY)");ok(e,s,"INSERT INTO t VALUES(1)");e.close_session(s);}
void timeout(const fs::path& path){
#ifdef _WIN32
    const char* previous=std::getenv("EDUDB_LOCK_TIMEOUT_MS");const auto saved=previous?std::string(previous):std::string();_putenv_s("EDUDB_LOCK_TIMEOUT_MS","60");
#endif
    Engine e(path.u8string(),3);
#ifdef _WIN32
    _putenv_s("EDUDB_LOCK_TIMEOUT_MS",saved.c_str());
#endif
    auto a=e.open_session(),b=e.open_session();ok(e,a,"CREATE TABLE t(id INTEGER PRIMARY KEY)");record(e,a);record(e,b);ok(e,a,"BEGIN");ok(e,a,"SELECT id FROM t WHERE id=15");ok(e,b,"BEGIN");error(e,b,"INSERT INTO t VALUES(15)","LOCK_TIMEOUT");auto state=e.diagnostics();need(state["queues"].empty(),"Timed-out SQL request removed from actual queue");ok(e,a,"COMMIT");ok(e,b,"ROLLBACK");ok(e,b,"INSERT INTO t VALUES(15)");e.close_session(a);e.close_session(b);
}
}
int main(){auto path=fs::temp_directory_path()/("edudb-range-sql-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));try{fs::create_directory(path);std::ofstream(path/"owned-test.marker")<<"range SQL";run(path/"redo");aries(path/"aries");timeout(path/"timeout");need(fs::equivalent(path.parent_path(),fs::temp_directory_path())&&path.filename().string().rfind("edudb-range-sql-",0)==0&&fs::exists(path/"owned-test.marker"),"Owned cleanup");fs::remove_all(path);std::cout<<"OBSERVATIONS "<<observations.dump()<<"\nPASS actual SQL range locks "<<checks<<" checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL SQL range after "<<checks<<": "<<e.what()<<"; evidence "<<path.u8string()<<"\n";return 1;}}
